// Shared shapes for app/core.js and app/ui.js (checked by `tsc --noEmit`, see tsconfig.json).
// Ambient declarations: no imports or exports, so every name here is global in both files.

/** One row of data/words.json: a deck word in Anki rank order. */
interface Word { rank: number; bg: string; en: string; pos: string; forms: string; learned?: boolean;
  /** the deck's topic (food, body, family, …) */
  cat?: string;
  /** clip key of the spoken word, in both voices (D-005) */
  au?: string }

/** A spoken part of a story title or paragraph (D-005): `bg` offsets from–to, voice k (Kalina) or b (Borislav),
 *  the clip key, and per word [start ms, from, to] for the read-along highlight. */
type AudioSeg = [number, number, 'k' | 'b', string, [number, number, number][]];

/** One practice sentence from data/sentences.json. */
interface Sentence {
  id: string; bg: string; nl: string; en: string;
  nl_alt: string[]; bg_alt: string[]; en_alt: string[];
  /** accepted with a "looser translation" note (D-014) */
  nl_loose?: string[]; en_loose?: string[];
  /** Bulgarian answers accepted only for the English prompt: the other "you" form (D-018) */
  bg_alt_en?: string[];
  lemmas: string[]; max_rank: number | null; tags: string[]; source: string; grammar?: string[];
  /** every word form of `bg` (lower case) -> its dictionary form (D-030) */
  words?: Record<string, string>;
  /** forms of address in `bg` (госпожо, господине), for the word card (D-027) */
  vocative?: string[];
  /** clip key of `bg`, in both voices (D-005) */
  au?: string;
  /** clip key of `nl` in the Dutch voice, the prompt of hands-free listening (D-034) */
  au_nl?: string;
}

interface GrammarTable { headers: string[]; rows: string[][] }
interface GrammarCard { id: string; stage: number; title: string; intro: string; table: GrammarTable; notes?: string[]; examples?: string[] }
interface GrammarData { version: number; pronouns: string[]; cards: GrammarCard[]; paradigms: any }

/** A reading story from data/stories.json (D-026), checked by tools/validate_stories.py. */
interface Story {
  id: string; level: number; title: { bg: string; nl: string; en: string; au?: AudioSeg[] };
  /** speakers: one name per quoted line, from data/cast.json; au: the spoken parts (D-005) */
  paragraphs: { bg: string; nl: string; en: string; speakers?: string[]; au?: AudioSeg[] }[];
  /** every word form of the title and text (lower case) -> its dictionary form in words.json (D-027) */
  words: Record<string, string>; names?: string[];
  /** forms of address that differ from the base form (петре -> Петър), lower case */
  vocative?: string[];
  /** glossed words above the level, with their meaning */
  extra?: Record<string, { nl: string; en: string }>;
  grammar?: string[]; max_rank: number | null; stage: number; word_count: number;
  /** comprehension questions (D-028); `answer` indexes `options` */
  questions: { q: { nl: string; en: string }; options: { nl: string; en: string }[]; answer: number }[];
}

/** Anything whose words can be tapped for their meaning (D-027, D-030): a story, or a practice sentence. */
interface WordSource { words: Record<string, string>; names?: string[]; extra?: Record<string, { nl: string; en: string }>; vocative?: string[]; lang?: 'nl' | 'en' }

/** What the learner did with one story (D-026, D-028). */
interface ReadingRecord { read?: number; quiz?: { at: number; score: number; total: number } }

/** window.TRAKIA_DATA, generated by tools/build_data.py into app/data.js. */
interface TrakiaData { words: Word[]; sentences: Sentence[]; grammar: GrammarData; stories: Story[]; learnedRank: number }

/** Learner settings (DEFAULTS in ui.js, persisted in localStorage). */
interface Settings {
  rank: number; tolerance: number; newPerSession: number;
  /** cards per session before retries (D-024) */
  sessionSize: number;
  directions: string; newOrder: string; lang: string; typoPct: number; bagOfWords: boolean;
  almostPolicy: string; almostFreePasses: number; retention: number; maxInterval: number; stage: number;
  strictPunct: boolean; strictYi: boolean; stripAccents: boolean; strictForms: boolean; translit: boolean; theme: string;
  /** cards in a row on one keyboard before switching (D-021); 1 alternates every card */
  dirRun: number;
  /** moving background (D-023): 'none' | 'fire' | 'video', a direct video URL, and the overlay opacity 0–90 */
  wallpaper: string; wallpaperUrl: string; wallpaperDim: number;
  /** audio (D-005), per device: sound on, play prompts by themselves, 'both' | 'k' | 'b', playback rate */
  sound: boolean; autoplay: boolean; voices: string; speed: number;
  /** dictation cards take over from mature reading cards (D-005 phase C); shared between devices */
  dictation: boolean;
  /** hands-free listening (D-034), per device: 'practice' | 'background', pause 'auto' or seconds, repeat the Bulgarian, minutes (0: no limit) */
  listenMode: string; listenPause: string; listenRepeat: boolean; listenLimit: number;
  /** deck words (D-035): new words a day, and no new words while today's reviews reach dailyMax; shared */
  newWords: number; dailyMax: number;
  freeSize?: number; fsrs?: Partial<FsrsOptions>;
}

interface FsrsOptions { retention: number; learningSteps: number[]; relearningSteps: number[]; maxInterval: number; fuzz: boolean }

/** Per-card progress record (key `<sentence id>|<direction>`), see D-001 and D-002. */
interface ProgressRecord {
  box: number; due: number; reps: number; lapses: number; streak: number; last: number;
  s?: number; d?: number; state?: 'learning' | 'review' | 'relearning'; step?: number; rating?: number;
  almosts?: number; orders?: number; lastRule?: string;
  /** time of the first answer ever; the first three answers stay young (D-024) */
  first?: number;
}

type Progress = Record<string, ProgressRecord>;

/** Everything that travels between devices: the export file and the synced gist (D-025). */
interface Snapshot {
  app: 'trakia'; version: number; exported?: string;
  /** only the shared settings, see DEVICE_SETTINGS in core.js */
  settings: Partial<Settings>;
  progress: Progress; userAlts: Record<string, string[]>; userSentences: Record<string, Sentence>; deleted: string[];
  log: (number | string)[][]; sessions: number[]; drills: Record<string, { ok: number; bad: number; last?: number }>; drillLog: (number | string)[][];
  /** when the shared settings or the deleted list last changed here, and the last "Reset all progress" */
  stamps: { settings?: number; deleted?: number; wiped?: number };
  /** per-card resets: card key -> time */
  cleared: Record<string, number>;
  /** stories read and quiz scores (D-026, D-028) */
  reading: Record<string, ReadingRecord>;
  /** totals of the days older than the last 30 (D-029) */
  days: Record<string, DaySummary>;
  /** words guessed in a sneak peek, by rank (D-031) */
  peeks: Record<string, { at: number; ok: boolean }>;
}

/** One compacted day (D-029): answers and drill answers as [wrong, almost, correct], session starts. */
interface DaySummary { a?: number[]; d?: number[]; s?: number }

/** localStorage `trakia.sync`: kept out of every snapshot, so the token never leaves this browser. */
interface SyncState { token?: string; gist?: string; url?: string; at?: number; error?: string }

/** What `$()` in ui.js returns: an element with the form-control fields the UI reads and writes.
 *  Looser than the DOM's per-tag interfaces, but it keeps field names and value types checked. */
interface AppElement extends HTMLElement {
  value: string; checked: boolean; disabled: boolean; selectedIndex: number; options: HTMLOptionsCollection;
  open: boolean; files: FileList | null; selectionStart: number | null; selectionEnd: number | null;
  rows: HTMLCollectionOf<HTMLTableRowElement>; min: string; max: string; step: string;
  placeholder: string; width: number; height: number; getContext: HTMLCanvasElement['getContext'];
  _t?: ReturnType<typeof setTimeout>; _bars?: { x: number; w: number; d: any; tot: number }[];
}

interface Window { TRAKIA_DATA: TrakiaData; TrakiaCore: any; XLSX?: any }
/** SheetJS, loaded on demand from cdnjs for .xlsx imports. */
declare const XLSX: any;
